#!/usr/bin/env python3
"""Generate complete vendor-neutral architecture pattern cards."""
from pathlib import Path

ROOT=Path.cwd(); OUT=ROOT/"bluebook/patterns"
patterns={
2:("模型与程序职责分离","1、3","Model处理语义不确定性；程序处理状态、权限、预算、业务规则和验证。","候选决策与权威执行混在模型中，导致越权、不可复现和无法审计。","Model → typed proposal → policy/validator → program execution → environment verification","开放式解释能力与确定性控制同时保留。","需要设计Schema、策略和验证器；边界过细可能增加延迟。","把业务不变量写进Prompt；模型直接写权威数据库。","当任务完全确定性时移除Model；当规则无法显式表达时仍保留受控模型节点。"),
3:("有界执行循环","3、9","Agent需要多轮观察和行动，但不能无限运行。","开放循环可能重复工具、耗尽费用或永不终止。","Observe → Decide → Act → Verify；由Runtime强制步骤、时间、费用和无进展上限","支持适应环境反馈并限制最坏成本。","预算过紧可能提前终止；需定义部分成功和恢复。","只在Prompt中要求停止；用模型自评作为唯一终止。","固定Workflow足够时退出循环。"),
4:("类型化状态与显式终态","3、9","长任务跨节点、进程和事件运行。","聊天历史无法可靠表达业务状态、所有权和完成语义。","使用版本化State Schema；终态区分成功、部分成功、阻塞、失败、取消和预算耗尽。","可恢复、测试和审计。","Schema演进和迁移增加工程工作。","把Model停止生成当作成功；状态只存在内存。","单次无状态调用无需持久运行状态。"),
5:("Checkpoint与持久恢复","3、9","任务包含长工具、审批、异步事件或进程重启。","进程故障会丢失进展，恢复可能重复副作用。","在副作用前后、等待前和重规划前保存版本化Checkpoint与Artifact引用。","支持恢复、迁移和人工接管。","持久化、兼容和清理复杂。","只保存聊天；Checkpoint不记录已完成副作用。","短且无副作用的原子调用可不持久化。"),
7:("准确载荷审批","9、11","Agent准备执行支付、发送、删除或部署等高影响动作。","批准模糊意图可能被不同金额、对象或政策版本复用。","审批绑定主体、资源、准确参数、政策版本、期限、Nonce与Action Digest；执行前重算。","人类知道批准什么，防止载荷漂移和Replay。","载荷变化需重新审批，增加交互。","只问“是否继续”；批准后允许模型改参数。","低影响、可逆且政策允许的动作无需人工审批。"),
8:("统一工具策略网关","6、11","多个模型、框架和协议调用组织工具。","分散授权导致某条路径绕过权限、预算或审计。","所有调用通过统一Schema、身份、政策、预算、审批和结果验证网关。","控制与模型/协议解耦。","网关成为关键依赖，需高可用和版本治理。","认为MCP Server天然可信；客户端各自实现权限。","无外部工具的只读生成不需要工具网关。"),
9:("稳定前缀与动态轨迹","4","多轮Agent希望复用缓存并减少上下文漂移。","时间戳、工具重排和动态信息混入前缀会降低稳定性。","把政策、工具和固定说明置于稳定前缀；运行状态、观察和用户信息放动态尾部。","提高可预测性并可能增加缓存复用。","需要版本化前缀；供应商缓存机制不同。","为了最新信息每轮重写System；承诺固定缓存收益。","单轮短请求或不支持缓存时收益有限。"),
10:("上下文压缩与Artifact外置","4、7、9","长任务积累网页、日志、代码和历史。","完整重放导致溢出、成本和干扰。","按丢弃、抽取、摘要、外置顺序缩减；大型载荷存Artifact并在上下文传URI、Hash和相关片段。","控制上下文规模，保留可追溯原文。","摘要可能丢信息，Artifact需要权限和生命周期。","摘要覆盖原证据；每轮重复粘贴大型内容。","上下文短且所有细节关键时不压缩。"),
11:("权限感知RAG","5、11","知识库包含多租户或分级内容。","先召回后过滤可能泄漏标题、向量或内容。","索引时绑定Tenant和ACL；检索前按Principal过滤；输出保留来源和权限。","降低跨租户泄漏并支持审计。","过滤可能降低召回，索引更新更复杂。","把权限写进Prompt；召回后让模型决定能否展示。","公开知识库无需用户级ACL，但仍需来源治理。"),
12:("治理化Memory写入","5、12","Agent希望跨会话保留偏好、事实或承诺。","自动记忆会持久化误解、攻击内容和敏感数据。","候选提取→分类→来源校验→同意/政策→冲突处理→版本化写入；支持查看、更正和删除。","获得持续个性化且保留用户控制。","写入延迟和治理成本增加。","把所有对话自动向量化；Memory覆盖权威数据库。","无需跨会话个性化时不写长期Memory。"),
13:("Proposer–Reviewer–Verifier","7、10、14","开放任务需要迭代提高代码、文档或视觉产物。","同一模型自评容易重复偏见，意见循环没有新信息。","Proposer生成；执行/渲染；Reviewer读取独立证据并给结构化缺口；Verifier按门禁终止。","利用环境反馈改进并可定位失败。","增加调用、延迟和终止设计。","Reviewer只看候选文本；没有轮数和最小增益。","确定性验证一次通过时无需Reviewer循环。"),
14:("快慢路径分离","8","实时语音或UI同时包含低延迟交互和慢检索/工具。","复杂推理阻塞反馈，用户无法打断。","快路径负责VAD、确认、取消、状态和安全；慢路径异步推理和工具，通过共享状态汇合。","降低感知延迟并支持打断。","并发状态和结果过期处理更复杂。","慢任务占用实时流；旧结果覆盖新意图。","无实时SLO的批处理无需快路径。"),
15:("Safe Point与级联取消","8、9、14","运行含子任务、工具和物理/外部副作用。","立即杀死可能留下半完成状态，不传播取消会产生孤儿任务。","在一致状态设置Safe Point；取消先阻止新工作、保存状态、清理资源并沿任务树级联。","可控停止和恢复。","某些阻塞工具无法协作取消，需要超时和强杀。","只停止UI输出；取消父任务但Worker继续。","不可中断的原子事务只在事务前后设置安全点。"),
16:("四级质量门","10","Agent变更需要从代码测试走向真实发布。","只做Smoke或只看在线指标无法兼顾速度与真实性。","Schema/Unit → Smoke → Offline Eval → Online Eval，逐级增加真实性和成本。","早期快速失败，发布证据完整。","维护数据集和环境成本较高。","用Smoke证明质量；线上试错无Canary。","纯确定性小改动仍可简化，但不得跳过相关回归。"),
17:("失败回流与回归闭环","10、12","生产不断出现离线集未覆盖的失败。","评估集静态会与真实分布脱节。","脱敏生产失败→首错归因→最小回归任务→候选修复→离线验证→灰度→继续监控。","评估随真实风险演进。","标签、隐私和去重需要治理。","直接把原对话加入Prompt或训练；只收成功样本。","失败不能合法保留时使用合成复现。"),
18:("外部能力优先更新","12、13","系统表现不足，需要改进。","直接训练参数昂贵、慢且难回滚，许多问题来自知识或控制。","按知识→Prompt/Skill→程序/Harness→模型参数选择最可控载体。","更快、更可解释和可回滚。","外部组件增多带来版本协调。","用训练修复时效知识或权限；规则无限堆积。","充分上下文和接口下仍稳定失败且有数据/验证器时进入训练。"),
19:("独立Agent工作区与Artifact交换","7、14","多个Worker并行处理文件、研究或生成产物。","共享可变目录导致覆盖，复制全上下文导致膨胀和泄漏。","每个Agent私有Scratch/Worktree；通过带Schema、Hash、来源和ACL的Artifact发布；单一Owner合并。","隔离冲突、减少消息体并增强追溯。","需要存储、合并和垃圾回收。","多个Agent直接编辑同一文件；消息中粘贴全部产物。","单Agent顺序任务无需多工作区。"),
}

def card(i,data):
 n,ch,ctx,problem,solution,benefit,cost,fail,exit=data
 return f'''# P{i:02d} {n}\n\n> 状态：Draft v0.1  \n> 主要章节：第{ch}章\n\n## Context\n\n{ctx}\n\n## Problem\n\n{problem}\n\n## Forces\n\n- 质量与正确性；\n- 延迟与成本；\n- 安全与合规；\n- 运维与可恢复性。\n\n## Solution\n\n```text\n{solution}\n```\n\n## Consequences\n\n### 收益\n\n{benefit}\n\n### 代价\n\n{cost}\n\n## Failure Modes\n\n{fail}\n\n## Implementation Sketch\n\n实现时使用类型化输入输出，记录版本、来源和Trace；权限、预算和终止由确定性代码执行。\n\n## Evidence\n\n- 蓝皮书章节：第{ch}章；\n- 实验卡：按具体实现绑定，不以代码存在替代运行证据；\n- 外部标准：涉及协议或安全标准时在发布前核验版本与日期。\n\n## Exit Criteria\n\n{exit}\n\n## Checklist\n\n- [ ] 问题与作用力真实存在。\n- [ ] 有更简单方案基线。\n- [ ] 失败模式可测试。\n- [ ] 权限、预算和恢复已定义。\n- [ ] 收益覆盖新增复杂度。\n'''

def main():
 OUT.mkdir(parents=True,exist_ok=True)
 for i,data in patterns.items():
  slug=re_slug(data[0]); (OUT/f"P{i:02d}-{slug}.md").write_text(card(i,data),encoding="utf-8")
 print(f"generated: {len(patterns)}")
def re_slug(s):
 names={2:"model-program-separation",3:"bounded-loop",4:"typed-state",5:"checkpoint-recovery",7:"exact-payload-approval",8:"tool-policy-gateway",9:"stable-prefix",10:"context-artifact",11:"permission-aware-rag",12:"governed-memory",13:"proposer-reviewer-verifier",14:"fast-slow-path",15:"safe-point-cancellation",16:"four-level-quality-gates",17:"failure-regression-loop",18:"external-first-update",19:"isolated-agent-workspace"}
 for k,v in patterns.items():
  if v[0]==s:return names[k]
if __name__=="__main__":main()
